import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P06-data_analysis/P06-1-data-analysis-thinking-course/00-see-the-essence-with-data.html","title":"00-0-数据给你一双看透本质的眼睛","lang":"zh-CN","frontmatter":{"title":"00-0-数据给你一双看透本质的眼睛","icon":"blog","date":"2025-10-12T17:19:37.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1761700178000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":21,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"2a228408afb510e9a3586cbb64ed881fb117a403","time":1761700178000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新文档标题以添加序号前缀"},{"hash":"e3cb64a2e7a1861b79323c94764f3b1b8cd2d5a1","time":1761656984000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据分析思维课程文档内容"},{"hash":"98822b12d63b1b90d85481bc2c105882851227a9","time":1761655180000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据分析课程介绍内容"},{"hash":"c9620a98fc00b487f9e6cd14733ca1c561852355","time":1761643099000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析课程图片和烹饪食谱内容"},{"hash":"cd28bfa8614376540734617b26b833adaecf7955","time":1761638392000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析课程内容介绍"},{"hash":"d9069dc9ea6bba9e51e67499198ac744ca048a75","time":1760342804000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据分析思维课程文档内容"},{"hash":"326966ff69f3e326e648e8204ab09c526b810b9e","time":1760270527000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析思维课程的内容示例"},{"hash":"958dc18715cd8176e4b73239a1dd8a128885b909","time":1760267525000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据思维课程文档结构和内容"},{"hash":"42de822131bb8f8d4eca4bb76496fd83fc2f6b30","time":1760263798000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新周报日期并添加新的测验和数据分析课程内容"},{"hash":"7548108b868e5f8dc986369422db8825596a5f4f","time":1748782067000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add FAQ articles for programming course: addressing students with prior experience and learning plans by age group"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"b2b6115182448c786784f88a3e325eec83b9c4fe","time":1747017995000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"<a href=\\"http://xn--FAQ04-y40k96e.md\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">更新FAQ04.md</a>，新增0～3岁和3～6岁的学习计划阶段"},{"hash":"2461710ae7016517f2fbd6cc4e6441ed8516e464","time":1747016674000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增FAQ04.md文档，提供每个年龄段的学习计划及辅导班信息"},{"hash":"70353fead4a0a1bfadb60ece94c0f3a9f80bfc08","time":1746926862000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文件夹名称"},{"hash":"ae8a442bae9aa264fee20e42267291df3a74b667","time":1746879162000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新食谱文档，优化标签和步骤格式"},{"hash":"9bfdcd8407ca12cf09f385c602eb1c60cc5f3c56","time":1745906987000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增 Vuepress 侧边栏自定义文档，包含自动生成侧边栏的说明及相关信息"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":9.42,"words":2827},"filePathRelative":"column/Python-Programming-Course/P06-data_analysis/P06-1-data-analysis-thinking-course/00-see-the-essence-with-data.md"}`),a={name:`00-see-the-essence-with-data.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/5c4c3352001d7bba6354458572e49186-CwiN2IW8.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你好，我是悦创。</p><p><strong><span style="color:orange;">数据给你一双看透本质的眼睛。</span></strong></p><p>在数据这个行业里，我一做就做了二十多年，数据已经成为了我生命中不可分割的一部分。</p><p>我经常听到这样一句话：“<strong><span style="color:orange;">数据是客观的，但是解读数据的人是主观的</span></strong>”。在我看来，数据这门科学就像中西医混合的一门医学，既要有西医的理论、分析模型以及实验，又需要有中医的望闻问切这些个人经验。</p><p>我们都生活在一个由数据组成的世界里，不管是工作还是过日子，数据其实无处不在。我觉得我还算是一个“<strong>中西结合</strong>”的人，所以我想把自己的西医部分（数据科学理论）与中医部分（个人数据经验）一并分享给你。</p><h2 id="_1-数据时代-思维为王" tabindex="-1"><a class="header-anchor" href="#_1-数据时代-思维为王"><span>1. 数据时代 ，思维为王</span></a></h2><p>前段时间，我的一个游戏分析师朋友告诉我，他的公司做了款游戏，这款游戏很受欢迎，他们分别开发了安卓、iOS、Pad 等等版本。他分析了已有的付费数据，发现安卓用户的付费率要高于 iOS 用户，所以他得出结论：<strong><span style="color:orange;">在公司开发资源有限的情况下，他们应该投入更多精力（或者提高优先级）优化安卓版本</span></strong>。</p><p>我听完之后，倒吸一口凉气。这个决策执行下去，这个公司可能在投入了很多 Android 开发工作后，却无法有更多的收入回报，最终导致这个很有前途的小公司破产。</p><p>你知道他是在哪里出错了吗？我给你一个提示：<strong>这个数据本身没问题，但是分析数据的逻辑出了问题</strong>，他犯了数据分析行业都熟知的叫“<strong>辛普森悖论</strong>”的错误。还不知道什么是“辛普森悖论”吗？不要担心，我会在后面的课程详细跟你讲。</p><p>这些年，随着技术的发展以及时代的变换，我也经常感叹，现在的数据真是比以前更容易获得和计算了——我们有最强大的计算工具、分析算法和浩如烟海的大数据。</p><p>但是，当我们沉醉于数据量之大、算法之精美时，却可能忘记了做数据分析的初衷和最基本的逻辑。你可要知道，不管是大数据还是小数据，只有经过客观合理地分析之后，才能真正产生价值。</p><p>所以我认为，<strong><span style="color:orange;">在这个数据为王的时代，我们缺乏的不是工具、算法，而是数据思维</span></strong>。这就好比过去，我们打猎用的是弓箭，看见了兔子就去射箭，虽然效率低，但是目标很明确。而现在我们拿着最高级的冲锋枪冲进了森林里，一通乱扫，却不知道打什么。</p><p>我希望这门课程，不仅能告诉你打什么，还能教会你弹无虚发、百步穿杨。</p><h2 id="_2-开这门课的初心" tabindex="-1"><a class="header-anchor" href="#_2-开这门课的初心"><span>2. 开这门课的初心</span></a></h2><p>在我过去 20 年的数据相关工作里，我曾经因为追求极致的技术而没有交付最终的业务结果，最后被老板一通批评；我也曾拿着一个片面的数据分析结果就给出了一个全面的分析解读答案；我还曾经在做管理决策的时候，用一个平均值来去看整体的收入状态和开发迭代速度，导致错失一些优秀的人才和客户；更有时候，我在听汇报的时候，没有甄别出来小伙伴写出来的因果倒置或者一些存在“<strong>幸存者偏差</strong>”的结论数据，导致走了弯路。</p><p>这些我经历过的教训，让我也意识到数据分析的常识非常重要。我开这门《数据分析思维课「核心」》的初衷就是希望能够用简单的生活和工作当中的例子，结合数据分析的原理，帮助你培养数据思维。</p><p>就如我们前面所说，有了数据是第一步，你怎么分析数据，那就是另外一门学问了。在分析数据的时候，你有没有掌握基本的数据分析方法，有没有站在前人的经验之上思考问题，也会决定着你做这件事情的段位，我希望我能通过这个专栏把这些逻辑都告诉给你。</p><p>在这门课当中，我不会“罗列”特别多的公式、复杂的推理、大量的程序等。我只是希望用各种各样的例子告诉你怎样用数据分析的角度来看待这个世界，与此同时也教会你一些数据分析最基本的知识。</p><p>当你学完这门课以后，我希望的效果是：<strong><span style="color:orange;">你再看待同一件事情的维度和以前不一样了，你可以用数据的维度来诠释你身边发生的事情，用数据的思维来做出你的判断</span></strong>。</p><p>为什么我把它做成这样一个通识课的类型，而不是一个专业课呢？我是这么考虑的：如果你知道自己需要什么，比如需要某一个深入的专业领域知识，那么你可以直接到网络搜索引擎去找，或者在“<a href="http://bornforthis.cn" target="_blank" rel="noopener noreferrer">bornforthis.cn</a>”里搜索相关的专业课。</p><p>而实际情况往往是你可能并不知道自己需要什么，或者怎么用数据分析去诠释一个问题。这时，你就需要有一门课把这些数据分析的相关知识串起来，扩大自己的认知边界，知道原来还可以利用这样的想法来分析这个问题。</p><h2 id="_3-你可以从这门课里得到什么" tabindex="-1"><a class="header-anchor" href="#_3-你可以从这门课里得到什么"><span>3. 你可以从这门课里得到什么</span></a></h2><p>做这门课的时候，我给自己定的第一个原则就是“场景化”。我讲的这些不应该是一些需要死记硬背的概念，而是你曾经经历、或者触手可及的案例。</p><p>所以在整个这门课的一开始，我会先将数据分析的基础概念和实际生活结合，让你能够轻松识别生活里的那些“伪科学”和“伪数据”。</p><p>然后我会给出基于这些数据分析基本概念的思路，和你分享一些常见的数据分析算法，去帮助你了解人工智能时代下的数据分析是怎样玩的，这其实是数据分析基础的延伸。</p><p>除此之外，我还会告诉你怎样去用数据和算法来分析解决一些具体的问题并做出实战。也会推荐给你一些我自己常用的分析工具以及这些工具的使用技巧。这样你可以快速地把前面的那些理论，直接应用你的实际工作和生活当中，提高你和数据相关的工作效率，让你在分析管理上也更加得心应手。</p><p>数据分析非常复杂，它融汇了数学、统计学、计算机科学、管理学等一系列的学科。</p><figure><img src="/assets/8d7e78dae9a1130166811550d59c20de-yIZPtV87.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这门课只是一个入门，无论你是文科生还是理科生，无论你是程序员还是产品经理，无论你是高管还是普通的初出茅庐的学生，通过这门课，<strong>我都希望能让你对数据分析产生兴趣，让你具有数据思维，以后不管是面对生活还是工作，都可以有一双通过数据看透事物本质的眼睛。</strong></p><p>当然，我想强调的是，并不是说只有工作场景才能用到这些数据分析知识，也并非有了大数据才能用到这些知识，数据分析应该是渗入到我们生活的每一个场景里。</p><p>比如去赌场玩俄罗斯轮盘，连续 10 次开小了，你心里可能会觉得连续 10 次小了，下一次开大的概率更高一些，然后就去押大，那实际上大的概率真的会高吗？听过后面的课后，你就会明白，这是典型的“<strong>赌徒谬误</strong>”，是错误的。</p><p>再比如，你带了一个十人的团队，每个人都有自己的优缺点和性格，每次一提到团队管理你就头大，因为内心总是混乱的，没有一条主线。但是不知道你想过没有，这十个人也是数据，你可以根据“四象限法”对他们进行分类，能力是纵轴，意愿是横轴……最后看看谁是你最应该提拔的人才。</p><p>所以，其实只要你有心，生活之中，处处都藏着数据的学问。</p><p>最后，我再重复下我的核心观点：<strong>这世界缺的真不是算法和技术，而是能用算法、技术解决实际问题的人</strong>。我希望能把自己学习到的诸多课程、项目的经验和阅读的大量书籍浓缩一下，深入浅出地用比较朴实和简单的语言让你理解什么是数据分析，以及怎么在自己的生活和工作当中更好地利用好数据做出更有效的决策。</p><p>“<strong>数据是有灵魂的，我将用我一生去追寻它</strong>”，这是我的座右铭，我发在这里，和你共勉。也欢迎你加入《数据分析思维课》，从今天开始，我们一起开启数据分析之旅！</p><p>当然，也欢迎你在留言区分享你对于数据的思考，以及你曾经用过的那些数据分析小知识。英国教育家约翰·纽曼曾经说过，最好的教育应该是让年轻人们生活在一起相互学习，我想，留言区就是我们最好的学习场地。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};